<?php require 'vendor/autoload.php'; $app = require_once 'bootstrap/app.php'; $app->make(Illuminate\Contracts\Console\Kernel::class)->bootstrap(); $umkms = App\Models\Umkm::all(); foreach($umkms as $u) { if (strpos($u->nama_usaha, 'Rajawali') !== false || strpos($u->nama_usaha, 'Mirasa') !== false) { echo $u->nama_usaha . ' | Lokasi: ' . $u->lokasi . ' (' . strlen($u->lokasi) . ' chars) | Alamat: ' . $u->alamat . PHP_EOL; } }
